@@ -0,0 +1,18 @@
+import { AppError } from "../errors.js";
+
+/** Creates a request-local store context sharing the persistent data and IDs. */
+export function forSite(store, site) {
+  if (!store.data.sites.some((entry) => entry.id === site))
+    throw new AppError("unknown_site", { id: site });
+  return Object.assign(Object.create(store), { site });
+}
+
+/** Checks whether a location belongs to the active site. */
+export function hasLocation(store, location) {
+  return store.data.locations.some((l) => l.id === location && l.site === (store.site ?? "main"));
+}
+
+/** Returns the batches held at the active site's locations. */
+export function siteBatches(store) {
+  return store.data.batches.filter((batch) => hasLocation(store, batch.location));
+}
