@@ -0,0 +1,32 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+test("site selection scopes inventory reads and writes across requests", async () => {
+  const { handle, store } = app();
+  const headers = { "X-Larder-Site": "annex" };
+  const annex = (path, body) => handle({ path, headers, method: body ? "POST" : "GET", body });
+  const batch = store.data.batches[0];
+  batch.location = "annex-fridge";
+  batch.expires = "2026-10-29";
+
+  assert.deepEqual((await annex("/batches")).body, [batch]);
+  assert.equal((await handle({ path: "/batches/1" })).status, 404);
+  assert.equal((await annex("/items/1")).body.onHand, 4);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 6);
+  assert.deepEqual((await annex("/alerts")).body.expiring, [batch]);
+  assert.equal((await annex("/reports/stock-value")).body.totalCents, 4 * store.data.items[0].priceCents);
+  assert.equal((await annex("/recipes/1/cook", { portions: 1 })).status, 409);
+  assert.equal((await annex("/stocktakes", { location: "dry" })).status, 400);
+
+  const take = (await annex("/stocktakes", { location: "annex-fridge" })).body;
+  const path = `/stocktakes/${take.id}`;
+  assert.equal((await handle({ method: "POST", path: path + "/finish" })).status, 404);
+  assert.equal((await annex(path + "/counts", { batchId: batch.id, counted: 3 })).status, 200);
+  assert.equal((await annex(path + "/finish", {})).status, 200);
+  assert.equal(batch.qty, 3);
+
+  const unknown = await handle({ path: "/items", headers: { "x-larder-site": "missing" } });
+  assert.equal(unknown.status, 400);
+  assert.equal(unknown.body.error.code, "unknown_site");
+});
